 text+='\nActual full-delivery evidence: '+json.dumps({'current_definitions':inv['current_definitions'],'admitted_versions':inv['admitted_source_versions'],'partial_drafts':inv['partial_drafts'],'missing_current_drafts':len(inv['missing_current_drafts']),'counts':inv['counts'],'local_graph_nodes':len(d['nodes']),'local_graph_edges':len(d['edges']),'joint_graph_nodes':inv['joint_declared_graph']['nodes'],'joint_graph_edges':inv['joint_declared_graph']['edges'],'joint_missing_counterparts':len(inv['joint_declared_graph']['missing_counterpart_packets']),'prior_seal_files':old['prior_candidate_files_preserved'],'frozen_typed_inputs':len(old['inputs']),'source_files_current':201,'retained_successful_profile_before_display_correction':1,'native_definition_or_profile_failures':0},sort_keys=True)+'.\n'
 assert len(re.findall(r'^## [0-9]+\.',text,re.M))==13 and len(text.split())>2500
 with (u/'DELIVERY-REVIEW.md').open('x') as f:f.write(text)
 print(json.dumps({'review_words':len(text.split()),'aspects':13,'owner_findings':18},indent=2))
